sys_script_include.script:
var ParentDateValidator = Class.create();
ParentDateValidator.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getParentDates: function() {

        // Retrieve the parent Twelve Week Cycle sys_id passed from the client script
        var parentSysId = this.getParameter('sysparm_parent_sysid');

        // If no sys_id was provided, return a structured error rather than null
        if (!parentSysId) {
            return JSON.stringify({
                error: 'No parent sys_id provided'
            });
        }

        // Instantiate a GlideRecord for the Twelve Week Cycle table
        var gr = new GlideRecord('x_942105_12_week_y_twelve_week_cycle');

        // Attempt to retrieve the parent record by sys_id — return structured error if not found
        if (!gr.get(parentSysId)) {
            gs.warn('ParentDateValidator: Record not found for sys_id - ' + parentSysId, 'ParentDateValidator');
            return JSON.stringify({
                error: 'Parent cycle record not found: ' + parentSysId
            });
        }

        // Read the start and end date field values from the parent record as strings
        var startDate = gr.getValue('start_date');
        var endDate = gr.getValue('end_date');

        // If either date field is unpopulated, return a structured error to prevent client-side failures
        if (!startDate || !endDate) {
            gs.warn('ParentDateValidator: Cycle dates missing on record - ' + parentSysId, 'ParentDateValidator');
            return JSON.stringify({
                error: 'Parent cycle dates are not fully configured'
            });
        }

        // Return the parent cycle date boundaries as a JSON string to the client script
        return JSON.stringify({
            start_date: startDate, // Parent cycle start date (yyyy-MM-dd)
            end_date: endDate // Parent cycle end date   (yyyy-MM-dd)
        });
    },

    type: 'ParentDateValidator'
});
